#!/bin/bash

# QIIME2 Analysis Script for 16S Nanopore Data
# Generated by Trae AI
#
# Usage: ./run_analysis.sh
#
# Prerequisites:
# - QIIME2 environment must be active (e.g., conda activate qiime2-2024.5)
# - manifest.tsv and sample-metadata.tsv must be present in the current directory

# Activate Conda Environment
source /home/lihui/anaconda3/etc/profile.d/conda.sh
conda activate qiime2-amplicon-2025.10

# Fix R environment conflicts
export LD_LIBRARY_PATH="$CONDA_PREFIX/lib/R/lib"
export R_HOME="$CONDA_PREFIX/lib/R"
unset R_LIBS_USER
unset R_LIBS_SITE

echo "R_HOME: $R_HOME"
echo "LD_LIBRARY_PATH: $LD_LIBRARY_PATH"

set -e # Exit on error
set -x # Echo commands

echo "Starting QIIME2 Analysis..."

# 1. Import Data
# Using SingleEndFastqManifestPhred33V2 for Nanopore fastq files
if [ ! -f "demux.qza" ]; then
    echo "Importing data..."
    qiime tools import \
      --type 'SampleData[SequencesWithQuality]' \
      --input-path manifest.tsv \
      --output-path demux.qza \
      --input-format SingleEndFastqManifestPhred33V2
fi

# 2. Summarize (Optional)
if [ ! -f "demux.qzv" ]; then
    echo "Summarizing demux data..."
    qiime demux summarize \
      --i-data demux.qza \
      --o-visualization demux.qzv
fi

# 3. Dereplication (VSEARCH)
if [ ! -f "rep-seqs.qza" ]; then
    echo "Dereplicating sequences..."
    qiime vsearch dereplicate-sequences \
      --i-sequences demux.qza \
      --o-dereplicated-table table.qza \
      --o-dereplicated-sequences rep-seqs.qza
fi

# 4. OTU Clustering (De Novo 97%)
# Note: For Nanopore data, exact parameters may vary. 97% is a standard starting point.
if [ ! -f "table-dn-97.qza" ]; then
    echo "Clustering features (OTUs)..."
    qiime vsearch cluster-features-de-novo \
      --i-table table.qza \
      --i-sequences rep-seqs.qza \
      --p-perc-identity 0.97 \
      --o-clustered-table table-dn-97.qza \
      --o-clustered-sequences rep-seqs-dn-97.qza
fi

# 5. Phylogenetic Tree
if [ ! -f "rooted-tree.qza" ]; then
    echo "Generating phylogenetic tree..."
    qiime phylogeny align-to-tree-mafft-fasttree \
      --i-sequences rep-seqs-dn-97.qza \
      --o-alignment aligned-rep-seqs.qza \
      --o-masked-alignment masked-aligned-rep-seqs.qza \
      --o-tree unrooted-tree.qza \
      --o-rooted-tree rooted-tree.qza
fi

# 6. Core Diversity Metrics
# IMPORTANT: Adjust --p-sampling-depth based on demux.qzv!
# Here we set a default of 1000. Increase this if your samples have more reads.
SAMPLING_DEPTH=50

echo "Running core diversity metrics (Sampling Depth: $SAMPLING_DEPTH)..."
if [ -d "core-metrics-results" ]; then
    rm -rf core-metrics-results
fi

qiime diversity core-metrics-phylogenetic \
  --i-phylogeny rooted-tree.qza \
  --i-table table-dn-97.qza \
  --p-sampling-depth $SAMPLING_DEPTH \
  --m-metadata-file sample-metadata.tsv \
  --output-dir core-metrics-results

# 7. Alpha Diversity Group Significance
# For Categorical Variable: group
echo "Analyzing Alpha Diversity Group Significance (group)..."
qiime diversity alpha-group-significance \
  --i-alpha-diversity core-metrics-results/shannon_vector.qza \
  --m-metadata-file sample-metadata.tsv \
  --o-visualization core-metrics-results/shannon-group-significance.qzv

# For Numeric Variable: days (Correlation)
echo "Analyzing Alpha Diversity Correlation (days)..."
qiime diversity alpha-correlation \
  --i-alpha-diversity core-metrics-results/shannon_vector.qza \
  --m-metadata-file sample-metadata.tsv \
  --o-visualization core-metrics-results/shannon-days-correlation.qzv

# 8. Beta Diversity Group Significance
echo "Analyzing Beta Diversity Group Significance (group)..."
qiime diversity beta-group-significance \
  --i-distance-matrix core-metrics-results/unweighted_unifrac_distance_matrix.qza \
  --m-metadata-file sample-metadata.tsv \
  --m-metadata-column group \
  --o-visualization core-metrics-results/unweighted-unifrac-group-significance.qzv

# Note on Taxonomy:
# To assign taxonomy, you need a classifier trained on the appropriate database (e.g. SILVA/Greengenes)
# for Nanopore full-length 16S.
# Example command (commented out):
# qiime feature-classifier classify-sklearn \
#   --i-classifier /path/to/classifier.qza \
#   --i-reads rep-seqs-dn-97.qza \
#   --o-classification taxonomy.qza
#
# qiime metadata tabulate \
#   --m-input-file taxonomy.qza \
#   --o-visualization taxonomy.qzv

echo "Analysis complete! Check the .qzv files in https://view.qiime2.org"
